"""URL slugs for titles."""
import re
import unicodedata


def _base_slug(title):
    """Return the unbounded slug, preserving the original normalization rules."""
    text = unicodedata.normalize("NFKD", title)
    text = "".join(ch for ch in text if not unicodedata.combining(ch)).lower()
    slug = re.sub(r"[^a-z0-9]+", "-", text).strip("-")
    return slug or "untitled"


def _limited_slug(base, max_length):
    if len(base) <= max_length:
        return base

    words = base.split("-")
    result = words[0][:max_length]
    if len(words[0]) > max_length:
        return result

    for word in words[1:]:
        candidate = result + "-" + word
        if len(candidate) > max_length:
            break
        result = candidate
    return result


def slugify(title, max_length=None):
    """Lower-case ASCII words joined by hyphens, optionally length-limited."""
    if max_length is not None and max_length < 1:
        raise ValueError("max_length must be at least 1")

    base = _base_slug(title)
    return base if max_length is None else _limited_slug(base, max_length)


def unique_slug(title, taken, max_length=None):
    """Return a slug not present in *taken*, adding an increasing numeric suffix."""
    if max_length is not None and max_length < 1:
        raise ValueError("max_length must be at least 1")

    base = _base_slug(title)
    candidate = slugify(title, max_length)
    if candidate not in taken:
        return candidate

    suffix_number = 2
    while True:
        suffix = "-" + str(suffix_number)
        if max_length is not None:
            base_length = max_length - len(suffix)
            if base_length < 1:
                raise ValueError("suffix leaves no room for a base slug")
            shortened = _limited_slug(base, base_length)
        else:
            shortened = base

        candidate = shortened + suffix
        if candidate not in taken:
            return candidate
        suffix_number += 1
